import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, texture, mul, add, vec3, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ─────────────────────────────────────────────────────────────────
  // 1. LOAD TEXTURES
  // ─────────────────────────────────────────────────────────────────
  let colorTexture, depthTexture;
  const texturePromises = [];

  if (config.imageUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
        colorTexture = tex;
        colorTexture.colorSpace = 'srgb';
      })
    );
  }

  if (config.depthMapUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.depthMapUrl).then(tex => {
        depthTexture = tex;
        depthTexture.colorSpace = 'linear';
      })
    );
  }

  // ─────────────────────────────────────────────────────────────────
  // 2. CREATE GEOMETRY (tessellated plane for displacement)
  // ─────────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(4, 2.5, 64, 64);

  // ─────────────────────────────────────────────────────────────────
  // 3. TSL MATERIAL WITH DISPLACEMENT & PARALLAX
  // ─────────────────────────────────────────────────────────────────
  const colorNode = colorTexture ? texture(colorTexture, uv()) : vec3(0.9, 0.9, 0.92);

  // Displacement based on depth map (scaled for subtle effect)
  let positionNode = undefined;
  if (depthTexture) {
    const depthSample = texture(depthTexture, uv());
    // Extract single channel and scale displacement intensity
    const displacementAmount = mul(depthSample.r, 0.08);
    positionNode = add(mul(3, displacementAmount), 0);
  }

  const material = new MeshStandardNodeMaterial({
    colorNode,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.15,
    clearcoatRoughness: 0.2,
  });

  if (positionNode) {
    material.positionNode = positionNode;
  }

  // ─────────────────────────────────────────────────────────────────
  // 4. MESH
  // ─────────────────────────────────────────────────────────────────
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // ─────────────────────────────────────────────────────────────────
  // 5. ACCENT RIM LIGHT (hero-grade lighting)
  // ─────────────────────────────────────────────────────────────────
  const rimLight = new THREE.PointLight(0xff2a38, 0.7, 8);
  rimLight.position.set(-3, 1.5, 1.5);
  group.add(rimLight);

  const fillLight = new THREE.PointLight(0xe8ecf2, 0.4, 6);
  fillLight.position.set(2, -1, 1);
  group.add(fillLight);

  // ─────────────────────────────────────────────────────────────────
  // 6. CINEMATIC PRIMITIVES
  // ─────────────────────────────────────────────────────────────────
  const primitiveRefs = [];

  // parallax-scroll (trigger: scroll)
  if (config.cinematicPrimitives?.some(p => p.name === 'parallax-scroll')) {
    const parallaxRef = ctx.primitives['parallax-scroll'](group, {
      intensity: 0.4,
    });
    primitiveRefs.push(parallaxRef);
  }

  // depth-rotate (trigger: hover)
  if (config.cinematicPrimitives?.some(p => p.name === 'depth-rotate')) {
    const depthRef = ctx.primitives['depth-rotate'](group, {
      maxDeg: 8,
    });
    primitiveRefs.push(depthRef);
  }

  // ─────────────────────────────────────────────────────────────────
  // 7. ENTRANCE ANIMATION (weighted-settle)
  // ─────────────────────────────────────────────────────────────────
  const entranceTimeline = gsap.timeline({ paused: true });

  group.position.y -= 0.15; // Start offset
  group.scale.set(0.98, 0.98, 0.98);

  entranceTimeline
    .to(group.position, { y: group.position.y + 0.15, duration: 0.7, ease: 'power3.out' }, 0)
    .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.2);

  entranceTimeline.play();

  // ─────────────────────────────────────────────────────────────────
  // 8. INTERACTION HANDLERS
  // ─────────────────────────────────────────────────────────────────
  group.userData.handlers = {
    hover: () => {
      gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.4,
        ease: 'power2.out',
      });
    },
    unhover: () => {
      gsap.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.4,
        ease: 'power2.out',
      });
    },
    click: () => {
      ctx.emit('navigate', { to: 'hub-home' });
    },
  };

  // ─────────────────────────────────────────────────────────────────
  // 9. CLEANUP
  // ─────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    primitiveRefs.forEach(ref => {
      if (ref?.cleanup) ref.cleanup();
    });
    geometry.dispose();
    material.dispose();
    if (colorTexture) colorTexture.dispose();
    if (depthTexture) depthTexture.dispose();
  };

  return group;
}
